import{_ as n,a0 as r,w as d,s as g,ao as f,I as o,x as a,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"apt-fast：飞一般的apt-get | LCTT x X-CMD","titleTemplate":false,"description":"apt-fast：飞一般的apt-get | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"apt-fast：飞一般的apt-get | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"apt-fast：飞一般的apt-get | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/apt-fast--Improve apt-get Download Speed","title":"apt-fast：飞一般的apt-get","tag":"201310","desc":""},"relativePath":"201310/apt-fast--Improve apt-get Download Speed.md","filePath":"[post].md"}'),l={name:"201310/apt-fast--Improve apt-get Download Speed.md"};function i(u,t,m,T,c,w){const p=r("Link");return d(),g("div",null,[t[11]||(t[11]=f(`<h1 id="apt-fast-飞一般的apt-get" tabindex="-1">apt-fast：飞一般的apt-get <a class="header-anchor" href="#apt-fast-飞一般的apt-get" aria-label="Permalink to “apt-fast：飞一般的apt-get”">​</a></h1><p>apt-fast是一个为 <strong>apt-get</strong> 和 <strong>aptitude</strong> 做的“ <strong>shell脚本封装</strong> ”，通过对每个包进行并发下载的方式可以大大减少APT的下载时间。apt-fast使用aria2c或axel下载管理器来减少APT下载时间。就像传统的apt-get包管理器一样，apt-fast支持几乎所有的apt-get功能，如， <strong>install</strong> , <strong>remove</strong> , <strong>update</strong> , <strong>upgrade</strong> , <strong>dist-upgrade</strong> 等等，并且更重要的是它也支持proxy。</p><p>###在Ubuntu上安装apt-fast</p><p>使用以下PPA去安装apt-fast。apt-fast开发者说：“ <strong>一些发行版，如PCLinux已经在他们默认的仓库中包括了apt-fast</strong> 。” 我希望它将来也包含在Ubuntu/Debian的默认仓库中。</p><p>添加apt-fast的PPA，在终端中输入以下命令。</p><pre><code>sudo add-apt-repository ppa:apt-fast/stable
</code></pre><p>用命令更新源：</p><pre><code>sudo apt-get update
</code></pre><p>使用命令安装apt-fast：</p><pre><code>sudo apt-get install apt-fast
</code></pre><p>在安装期间，它将要求你输入下载包的最大链接数。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/sk@sk-_003.png" alt=""></p><p>在下一个对话框里面，会问你是否要禁止apt-fast的确认对话框。选择No并继续安装。如果你选择Yes，apt-fast在安装软件包时不会问你确认与否。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/sk@sk-_0041.png" alt=""></p><p>我发现 <strong>aria2</strong> 下载管理器已经随着apt-fast的安装而自动安装。所以，你不必单独安装aria2。</p><p>如果你想重新配置apt-fast选项，你可以使用命令：</p><pre><code>sudo dpkg-reconfigure apt-fast
</code></pre><p>###用法</p><p>与apt-get功能相似，我们可以使用：</p><pre><code>apt-fast install package

apt-fast remove package

apt-fast update

apt-fast upgrade

apt-fast dist-upgrade
</code></pre><p>及更多命令。</p><p>工作中的apt-fast包管理器：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/sk@sk-_0051.png" alt=""></p><p>###创建别名（可选）</p><p>编辑 <strong>~/.bashrc</strong> 文件在末尾添加下面这行。</p><pre><code>alias apt-get=&#39;apt-fast&#39;
</code></pre><p>或者简单运行以下命令在你的 <strong>~/.bashrc</strong> 中添加它。</p><pre><code>sudo echo &quot;alias apt-get=&#39;apt-fast&#39;&quot; &gt;&gt; ~/.bashrc
</code></pre><p>从现在每当你运行apt-get命令去移除，更新和升级包时，它将在后台自动使用apt-fast。听起来很酷吧？</p><p>在测试期间，当下载包时我发现它与apt-get相比非常快。试一试，你一定会赞同我的看法。感谢阅读！！</p><hr>`,31)),o("p",null,[t[1]||(t[1]=a("via: ",-1)),e(p,{href:"http://www.unixmen.com/improve-apt-get-download-speed-apt-fast/"},{default:s(()=>[...t[0]||(t[0]=[a("http://www.unixmen.com/improve-apt-get-download-speed-apt-fast/",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=a("译者：",-1)),e(p,{href:"https://github.com/Vito"},{default:s(()=>[...t[2]||(t[2]=[a("Vito",-1)])]),_:1}),t[5]||(t[5]=a(" 校对：",-1)),e(p,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[3]||(t[3]=[a("Caroline",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=a("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[a("LCTT",-1)])]),_:1}),t[9]||(t[9]=a(" 原创翻译，",-1)),e(p,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[a("Linux中国",-1)])]),_:1}),t[10]||(t[10]=a(" 荣誉推出",-1))])])}const P=n(l,[["render",i]]);export{k as __pageData,P as default};
